    assertTrue(equalObj.accept(val));
}

@Test
public void notEqual() {
    NotEqual notEqualObj = new NotEqual(doubleCompare);
    byte[] val = getBytes(11.0d);
    assertTrue(notEqualObj.accept(val));
    val = getBytes(10.5d);
    assertFalse(notEqualObj.accept(val));
}

@Test
