    byte[] val = getBytes(11.0d);
    assertTrue(greaterThanObj.accept(val));
    val = getBytes(4.5d);
    assertFalse(greaterThanObj.accept(val));
    val = getBytes(10.5d);
    assertFalse(greaterThanObj.accept(val));
