    Decimal128.subtract(two, one, result, (short) 2);
    assertEquals(0, new Decimal128(1L, (short) 0).compareTo(result));
    Decimal128.subtract(two, two, result, (short) 1);
    assertEquals(0, zero.compareTo(result));
