@Test
public void testPattern1() {
    // Joda pattern matching expects fractional seconds length to match
    // the number of 'S' in the pattern. So if you want to match .1, .12, .123,
    // you need 3 different patterns with .S, .SS, .SSS
    String[] patterns = { // ISO-8601 timestamps
    "yyyy-MM-dd'T'HH:mm:ss", "yyyy-MM-dd'T'HH:mm:ss.S", "yyyy-MM-dd'T'HH:mm:ss.SS", "yyyy-MM-dd'T'HH:mm:ss.SSS", "yyyy-MM-dd'T'HH:mm:ss.SSSS" };
    TimestampParser tp = new TimestampParser(patterns);
    ValidTimestampCase[] validCases = { new ValidTimestampCase("1945-12-31T23:59:59.0", Timestamp.valueOf("1945-12-31 23:59:59.0")), new ValidTimestampCase("2001-01-01 00:00:00.100", Timestamp.valueOf("2001-01-01 00:00:00.100")), new ValidTimestampCase("2001-01-01 00:00:00.001", Timestamp.valueOf("2001-01-01 00:00:00.001")), // Joda parsing only supports up to millisecond precision
    new ValidTimestampCase("1945-12-31T23:59:59.1234", Timestamp.valueOf("1945-12-31 23:59:59.123")), new ValidTimestampCase("1970-01-01T00:00:00", Timestamp.valueOf("1970-01-01 00:00:00")), new ValidTimestampCase("1970-4-5T6:7:8", Timestamp.valueOf("1970-04-05 06:07:08")), // Default timestamp format still works?
    new ValidTimestampCase("2001-01-01 00:00:00", Timestamp.valueOf("2001-01-01 00:00:00")), new ValidTimestampCase("1945-12-31 23:59:59.1234", Timestamp.valueOf("1945-12-31 23:59:59.1234")) };
    String[] invalidCases = { "1945-12-31-23:59:59", // our pattern didn't specify 5 decimal places
    "1945-12-31T23:59:59.12345", "12345" };
    testValidCases(tp, validCases);
    testInvalidCases(tp, invalidCases);
}

