                Assert.assertEquals(1, aggrStats.getColStatsSize());
                ColumnStatisticsObj cso = aggrStats.getColStats().get(0);
                Assert.assertEquals("col1", cso.getColName());
                Assert.assertEquals("boolean", cso.getColType());
