    Assert.assertEquals(0, rsp.getResponseCode());
    rsp = driver.run("describe alter_renamed1");
    Assert.assertEquals(0, rsp.getResponseCode());
    rsp = driver.run("describe alterrename1");
    Assert.assertEquals(10001, rsp.getResponseCode());
}

