    verifySetup("SELECT a from " + dbName + ".ptned_empty", empty);
    verifySetup("SELECT * from " + dbName + ".unptned_empty", empty);
    // Now, we load data into the tables, and see if an incremental
    // repl drop/load can duplicate it.
