        assertEquals(2, cArgCaptor.getAllValues().size());
        ContainerId t1CId = cArgCaptor.getAllValues().get(0).getId();
        reset(tsWrapper.mockAppCallback);
        // At this point. 2 tasks running - both at priority 2.
