        tsWrapper.awaitLocalTaskAllocations(4);
        verify(tsWrapper.mockAppCallback, times(1)).taskAllocated(eq(task4), eq(clientCookie4), any(Container.class));
    } finally {
        tsWrapper.shutdown();
    }
}

