    Assert.assertTrue(resultLen == sentenceOneLen);
    Assert.assertTrue(StringExpr.characterCount(sentenceOne, 0, sentenceOneLen - 3) == 9);
    resultLen = StringExpr.rightTrim(sentenceOne, 0, sentenceOneLen - 3);
