    resultLen = StringExpr.rightTrimAndTruncate(multiByte, 0, 5, 2);
    Assert.assertTrue(resultLen == 4);
    Assert.assertTrue(StringExpr.characterCount(multiByte, 0, resultLen) == 2);
    addMultiByteCharRightPadded1_3(multiByte);
