    verifyTable.add(key2);
    verifyTable.verify(map);
    long key3 = key2 += 1;
    hashSetResult = map.createHashSetResult();
    joinResult = map.contains(key3, hashSetResult);
    assertTrue(joinResult == JoinUtil.JoinResult.NOMATCH);
}

