@Test
public void testDouble() throws Exception {
    Random r = new Random(1234);
    TimestampColumnVector timestampColVector = new TimestampColumnVector();
    Timestamp[] randTimestamps = new Timestamp[VectorizedRowBatch.DEFAULT_SIZE];
    for (int i = 0; i < VectorizedRowBatch.DEFAULT_SIZE; i++) {
        Timestamp randTimestamp = RandomTypeUtil.getRandTimestamp(r);
        randTimestamps[i] = randTimestamp;
        timestampColVector.set(i, randTimestamp);
    }
    for (int i = 0; i < VectorizedRowBatch.DEFAULT_SIZE; i++) {
        Timestamp retrievedTimestamp = timestampColVector.asScratchTimestamp(i);
        Timestamp randTimestamp = randTimestamps[i];
        if (!retrievedTimestamp.equals(randTimestamp)) {
            assertTrue(false);
        }
        double randDouble = TimestampUtils.getDouble(randTimestamp);
        double retrievedDouble = timestampColVector.getDouble(i);
        if (randDouble != retrievedDouble) {
            assertTrue(false);
        }
    }
}

@Test
public void testBasicFilterOperator() throws HiveException {
    VectorFilterOperator vfo = getAVectorFilterOperator();
    vfo.initialize(hconf, null);
    VectorExpression ve1 = new FilterLongColGreaterLongColumn(0, 1);
    VectorExpression ve2 = new FilterLongColEqualDoubleScalar(2, 0);
    VectorExpression ve3 = new FilterExprAndExpr();
    ve3.setChildExpressions(new VectorExpression[] { ve1, ve2 });
    vfo.setFilterCondition(ve3);
    FakeDataReader fdr = new FakeDataReader(1024 * 1, 3);
    VectorizedRowBatch vrg = fdr.getNext();
    vfo.getConditionEvaluator().evaluate(vrg);
    //Verify
    int rows = 0;
    for (int i = 0; i < 1024; i++) {
        LongColumnVector l1 = (LongColumnVector) vrg.cols[0];
        LongColumnVector l2 = (LongColumnVector) vrg.cols[1];
        LongColumnVector l3 = (LongColumnVector) vrg.cols[2];
        if ((l1.vector[i] > l2.vector[i]) && (l3.vector[i] == 0)) {
            rows++;
        }
    }
    Assert.assertEquals(rows, vrg.size);
}

@Test
public void testBasicFilterLargeData() throws HiveException {
    VectorFilterOperator vfo = getAVectorFilterOperator();
    vfo.initialize(hconf, null);
    VectorExpression ve1 = new FilterLongColGreaterLongColumn(0, 1);
    VectorExpression ve2 = new FilterLongColEqualDoubleScalar(2, 0);
    VectorExpression ve3 = new FilterExprAndExpr();
    ve3.setChildExpressions(new VectorExpression[] { ve1, ve2 });
    vfo.setFilterCondition(ve3);
    FakeDataReader fdr = new FakeDataReader(16 * 1024 * 1024, 3);
    long startTime = System.currentTimeMillis();
    VectorizedRowBatch vrg = fdr.getNext();
    while (vrg.size > 0) {
        vfo.process(vrg, 0);
        vrg = fdr.getNext();
    }
    long endTime = System.currentTimeMillis();
    System.out.println("testBaseFilterOperator Op Time = " + (endTime - startTime));
    //Base time
    fdr = new FakeDataReader(16 * 1024 * 1024, 3);
    long startTime1 = System.currentTimeMillis();
    vrg = fdr.getNext();
    LongColumnVector l1 = (LongColumnVector) vrg.cols[0];
    LongColumnVector l2 = (LongColumnVector) vrg.cols[1];
    LongColumnVector l3 = (LongColumnVector) vrg.cols[2];
    int rows = 0;
    for (int j = 0; j < 16 * 1024; j++) {
        for (int i = 0; i < l1.vector.length && i < l2.vector.length && i < l3.vector.length; i++) {
            if ((l1.vector[i] > l2.vector[i]) && (l3.vector[i] == 0)) {
                rows++;
            }
        }
    }
    long endTime1 = System.currentTimeMillis();
    System.out.println("testBaseFilterOperator base Op Time = " + (endTime1 - startTime1));
}

@Test
public void testMemoryPressureFlush() throws HiveException {
    List<String> mapColumnNames = new ArrayList<String>();
    mapColumnNames.add("Key");
    mapColumnNames.add("Value");
    VectorizationContext ctx = new VectorizationContext("name", mapColumnNames);
    GroupByDesc desc = buildKeyGroupByDesc(ctx, "max", "Value", TypeInfoFactory.longTypeInfo, "Key", TypeInfoFactory.longTypeInfo);
    // Set the memory treshold so that we get 100Kb before we need to flush.
    MemoryMXBean memoryMXBean = ManagementFactory.getMemoryMXBean();
    long maxMemory = memoryMXBean.getHeapMemoryUsage().getMax();
    float treshold = 100.0f * 1024.0f / maxMemory;
    desc.setMemoryThreshold(treshold);
    CompilationOpContext cCtx = new CompilationOpContext();
    Operator<? extends OperatorDesc> groupByOp = OperatorFactory.get(cCtx, desc);
    VectorGroupByOperator vgo = (VectorGroupByOperator) Vectorizer.vectorizeGroupByOperator(groupByOp, ctx);
    FakeCaptureOutputOperator out = FakeCaptureOutputOperator.addCaptureOutputChild(cCtx, vgo);
    vgo.initialize(hconf, null);
    this.outputRowCount = 0;
    out.setOutputInspector(new FakeCaptureOutputOperator.OutputInspector() {

        @Override
        public void inspectRow(Object row, int tag) throws HiveException {
            ++outputRowCount;
        }
    });
    Iterable<Object> it = new Iterable<Object>() {

        @Override
        public Iterator<Object> iterator() {
            return new Iterator<Object>() {

                long value = 0;

                @Override
                public boolean hasNext() {
                    return true;
                }

                @Override
                public Object next() {
                    return ++value;
                }

                @Override
                public void remove() {
                }
            };
        }
    };
    FakeVectorRowBatchFromObjectIterables data = new FakeVectorRowBatchFromObjectIterables(100, new String[] { "long", "long" }, it, it);
    // The 'it' data source will produce data w/o ever ending
    // We want to see that memory pressure kicks in and some
    // entries in the VGBY are flushed.
    long countRowsProduced = 0;
    for (VectorizedRowBatch unit : data) {
        countRowsProduced += 100;
        vgo.process(unit, 0);
        if (0 < outputRowCount) {
            break;
        }
        // Set an upper bound how much we're willing to push before it should flush
        // we've set the memory treshold at 100kb, each key is distinct
        // It should not go beyond 100k/16 (key+data)
        assertTrue(countRowsProduced < 100 * 1024 / 16);
    }
    assertTrue(0 < outputRowCount);
}

