        }
    };
    Wrapper<String> one = ic.retrieve("one", null);
    Wrapper<String> two = ic.retrieve("two", null);
    Wrapper<String> anotherOne = ic.retrieve("one", null);
    assertSame(one, anotherOne);
    Wrapper<String> anotherTwo = ic.retrieve("two", null);
