    assertEquals(0, hcw2.compareTo(hcw1));
    // leading spaces are significant
    hcw1.set(" abcd", 5);
    hcw2.set("abcd", 5);
    assertFalse(hcw1.equals(hcw2));
    assertFalse(hcw2.equals(hcw1));
    assertFalse(0 == hcw1.compareTo(hcw2));
